package com.example.lending.domain;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

/** 한 책의 소진되지 않은 예약을 줄 선 순서대로 담는다. */
public class ReservationQueue {

    private final UUID bookId;
    private final List<Reservation> waiting;

    public ReservationQueue(UUID bookId, List<Reservation> waiting) {
        this.bookId = bookId;
        this.waiting = List.copyOf(waiting);
    }

    public List<Reservation> getWaiting() {
        return waiting;
    }

    /** 예약이 없으면 누구나 빌릴 수 있다. 있으면 맨 앞 예약자만 빌릴 수 있고, 그 예약은 소진된다. */
    public Optional<Reservation> claimFor(UUID memberId) {
        if (waiting.isEmpty()) {
            return Optional.empty();
        }
        Reservation first = waiting.get(0);
        if (!first.getMemberId().equals(memberId)) {
            throw new ReservedForOtherException(bookId, memberId);
        }
        first.fulfill();
        return Optional.of(first);
    }
}
