package com.example.lending.domain;

import java.util.Objects;
import java.util.UUID;

public class Reservation {

    private final UUID id;
    private final UUID bookId;
    private final UUID memberId;
    private boolean fulfilled;

    private Reservation(UUID id, UUID bookId, UUID memberId, boolean fulfilled) {
        this.id = Objects.requireNonNull(id, "id");
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        this.memberId = Objects.requireNonNull(memberId, "memberId");
        this.fulfilled = fulfilled;
    }

    public static Reservation place(UUID bookId, UUID memberId) {
        return new Reservation(UUID.randomUUID(), bookId, memberId, false);
    }

    public static Reservation reconstitute(UUID id, UUID bookId, UUID memberId, boolean fulfilled) {
        return new Reservation(id, bookId, memberId, fulfilled);
    }

    public void fulfill() {
        this.fulfilled = true;
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public boolean isFulfilled() {
        return fulfilled;
    }
}
