package com.example.lending.application.service;

import com.example.lending.application.port.in.GetBookReservationsUseCase;
import com.example.lending.application.port.in.ReserveBookUseCase.QueuedReservation;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadReservationsPort;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.Reservation;
import com.example.lending.domain.ReservationQueue;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.UUID;
import java.util.stream.IntStream;

@Service
@Transactional(readOnly = true)
public class GetBookReservationsService implements GetBookReservationsUseCase {

    private final LoadBookPort loadBookPort;
    private final LoadReservationsPort loadReservationsPort;

    public GetBookReservationsService(LoadBookPort loadBookPort, LoadReservationsPort loadReservationsPort) {
        this.loadBookPort = loadBookPort;
        this.loadReservationsPort = loadReservationsPort;
    }

    @Override
    public List<QueuedReservation> getReservations(UUID bookId) {
        loadBookPort.loadBook(bookId).orElseThrow(() -> new BookNotFoundException(bookId));
        ReservationQueue queue = loadReservationsPort.loadQueue(bookId);
        List<Reservation> waiting = queue.getWaiting();
        return IntStream.range(0, waiting.size())
                .mapToObj(i -> new QueuedReservation(waiting.get(i), queue.positionAt(i)))
                .toList();
    }
}
