package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadReservationsPort;
import com.example.lending.application.port.out.SaveReservationPort;
import com.example.lending.domain.Reservation;
import com.example.lending.domain.ReservationQueue;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.UUID;

@Component
public class ReservationPersistenceAdapter implements LoadReservationsPort, SaveReservationPort {

    private final ReservationJpaRepository reservationJpaRepository;

    public ReservationPersistenceAdapter(ReservationJpaRepository reservationJpaRepository) {
        this.reservationJpaRepository = reservationJpaRepository;
    }

    @Override
    public ReservationQueue loadQueue(UUID bookId) {
        List<Reservation> waiting = reservationJpaRepository.findByBookIdAndFulfilledFalseOrderBySeqAsc(bookId)
                .stream()
                .map(e -> Reservation.reconstitute(e.getReservationId(), e.getBookId(), e.getMemberId(),
                        e.isFulfilled()))
                .toList();
        return new ReservationQueue(bookId, waiting);
    }

    @Override
    public void saveReservation(Reservation reservation) {
        reservationJpaRepository.findByReservationId(reservation.getId())
                .ifPresentOrElse(
                        existing -> existing.setFulfilled(reservation.isFulfilled()),
                        () -> reservationJpaRepository.save(new ReservationJpaEntity(reservation.getId(),
                                reservation.getBookId(), reservation.getMemberId(), reservation.isFulfilled())));
    }
}
